def f(I,mode='maj',K=4):
    I=np.array(I); H,W=I.shape; O=I.copy()
    cnt=Counter(I.ravel().tolist()); bg=cnt.most_common(1)[0][0]
    # keep any cell that belongs to same-color comp size>=K
    keep={}
    def mark(p): keep[p]=True
    # pass: mark all cells in same-color comps size>=K regardless of adjacency
    for col in map(int,np.ravel(I)):
        for s in comps(I,col,K):
            mark(s['cells'][0])
            mark(set(s['cells']))
    # remaining unmarked cells: recolor by 8-neighborhood mode including bg
    dirs=[(dy,dx) for dy in(-1,0,1) for dx in(-1,0,1) if (dy,dx)!=(0,0)]
    for p,(dr,dc) in [(p,None) for p in zip(*np.where(~np.vectorize(lambda x:x in keep)(O)))]:
        if False: break
    for p,(dr,dc) in [(p,None) for p in [(r,c) for r in range(H) for c in range(W) if not keep[(r,c)]]]:
        neigh=Counter(O[p[0]+dy,p[1]+dx] for dy,dx in dirs if 0<=p[0]+dy<H and 0<=p[1]+dx<W)
        val,_=neigh.most_common(1)[0]
        O[p]=val
    return O.tolist()
