def f(I):
    I=np.array(I); H,W=I.shape; O=I.copy()
    cnt=Counter(I.ravel().tolist()); bg=cnt.most_common(1)[0][0]
    # Step1: remove tiny isolated comps entirely -> set to bg
    keep=set()
    for col in set(map(int,np.ravel(I)))-{bg}:
        for s in comps(I,col):
            if s['n_cells']>=3: keep.update(s['cells'])
    dirs=[(dy,dx) for dy in(-1,0,1) for dx in(-1,0,1) if (dy,dx)!=(0,0)]
    for p in [(r,c) for r in range(H) for c in range(W) if p not in keep]:
        neigh=Counter(O[p[0]+dy,p[1]+dx] for dy,dx in dirs if 0<=p[0]+dy<H and 0<=p[1]+dx<W)
        v,_=neigh.most_common(1)[0]
        if v==bg: continue
        O[p]=v
    # Step2: fill holes inside solid structures' bboxes
    for col in set(map(int,np.ravel(I)))-{bg}:
        for s in comps(I,col):
            if s['n_cells']>=4:
                rs=[q[0] for q in s['cells']]; cs=[q[1] for q in s['cells']]
                y0,y1,x0,x1=min(rs),max(rs),min(cs),max(cs)
                cover=sum(1 for r in range(y0,y1+1) for c in range(x0,x1+1) if O[r,c]==col)
                if cover>=(y1-y0+1)*(x1-x0+1)*0.7:
                    for r in range(y0,y1+1):
                        for c in range(x0,x1+1):
                            if O[r,c]!=col:
                                O[r,c]=col
    return O.tolist()
