def comps_of_colors(I, allowed):
    H,W=I.shape; seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            if I[r,c] in allowed and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); comp=[]
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and I[ny,nx] in allowed and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                rs=[q[0] for q in comp]; cs=[q[1] for q in comp]
                res.append({'cells':set(comp),'color':int(I[r,c]),'n_cells':len(comp)})
    return res
def try_rule(I, noise_thr, min_frac):
    I=np.array(I); H,W=I.shape; O=I.copy()
    cnt=Counter(I.ravel().tolist()); bg=cnt.most_common(1)[0][0]
    nonbg=set(map(int,np.ravel(I)))-{bg}
    # noise color = colors whose cells ALL belong to tiny comps
    noise={c for c in nonbg if all(s['n_cells']<=noise_thr for s in comps_of_colors(np.array(I),{c}))}
    dirs8=[(dy,dx) for dy in(-1,0,1) for dx in(-1,0,1) if (dy,dx)!=(0,0)]
    for r in range(H):
        for c in range(W):
            if int(I[r,c]) not in noise: continue
            nsum=0; best={}
            for dy,dx in dirs8:
                rr,cc=r+dy,c+dx
                if 0<=rr<H and 0<=cc<W:
                    v=int(I[rr,cc])
                    if v==bg: continue
                    nsum+=1
                    best[v]=best.get(v,0)+1
            if nsum==0: continue
            val,_=sorted(best.items(), key=lambda kv:(-(kv[1]),min(kv[0])))[0]
            frac=val/nsum
            if frac>=min_frac: O[r,c]=val
            else: O[r,c]=bg
    return O.tolist()
