import collections
def runinfo(g,r,c):
    # length of maximal horizontal run through (r,c) if non-bg; similarly vertical
    h0=g[r][c]
    L=1; c2=c
    while 0<c2<len(g[0]) and g[r][c2]==h0: c2+=1
    while c>L-1 and g[r][c-1]==h0: c-=1; L-=1
    R=L
    r2=r
    while r2>0 and g[r2][c]==h0: r2-=1
    while r2<h-1 and g[r2+1][c]==h0: r2+=1
    return (L,R)
